/** Read-model classification shared by report/detail and collection queries.
 * Ledger values remain intact when a requested closing valuation is unavailable. */
export function simulationEvaluationEligibility(head={}){
 if(head.config?.assetMode==='UPBIT_EVENT_UNIVERSE')return multiEventEvaluationEligibility(head);
 if(head.config?.assetMode==='UPBIT_EVENT_STREAM')return eventEvaluationEligibility(head);
 const processed=head.core?.totals?.decisionCount??head.processed??0,warmup=head.core?.totals?.warmupCount??head.warmup??0,ready=Math.max(0,processed-warmup),total=head.core?.coverage?.totalDecisionFrames??head.total??0;
 const portfolio=head.config?.assetMode==='UPBIT_BTC_PORTFOLIO',account=head.core?.account??head.account??head.report?.account,staleFrames=head.core?.totals?.staleValuationFrames??head.staleValuationFrames??head.report?.quality?.staleValuationFrames??0,endAt=head.config?.endAt;
 const incompleteHeldInstruments=portfolio&&head.status==='COMPLETED'?(account?.positions??[]).filter(p=>p.quantity>0&&p.priceAsOf!==endAt).map(p=>({instrumentId:p.instrumentId,priceAsOf:p.priceAsOf??null})):[];
 const incompleteValuation=portfolio&&(staleFrames>0||incompleteHeldInstruments.length>0),wholeWindowComparable=head.status==='COMPLETED'&&ready===total&&!incompleteValuation;
 return {basis:'PERSISTED_SIMULATION_DECISION_READINESS_V1',executionMode:head.config?.mode,status:!processed?'NOT_EXECUTED':!ready?'NO_EVALUABLE_DECISIONS':head.status!=='COMPLETED'?'IN_PROGRESS':warmup||incompleteValuation?'PARTIAL_WINDOW':'FULL_WINDOW',readyDecisions:ready,warmupDecisions:warmup,processedDecisions:processed,totalDecisions:total,wholeWindowComparable,metricsBasis:'ACCOUNT_LEDGER',originalMetricsPreserved:true,...(portfolio?{valuation:{status:incompleteValuation?'PARTIAL':'COMPLETE',reason:incompleteValuation?'STALE_PORTFOLIO_VALUATION':null,staleFrames,requiredAsOf:endAt??null,accountAsOf:account?.asOf??null,finalEquity:account?.equity??null,quoteCurrency:'BTC',incompleteHeldInstruments}}:{})};
}

function multiEventEvaluationEligibility(head){
 const processed=head.core?.cursor??head.progress?.processed??head.rowsCounts?.decisions??head.processed??0,total=head.core?.coverage?.totalDecisionFrames??head.coverage?.totalDecisionFrames??head.total??0,warmup=head.core?.totals?.warmupCount??head.report?.quality?.warmupCount??head.warmup??0,ready=Math.max(0,processed-warmup),completed=head.status==='COMPLETED';
 const nav=head.report?.nativeNAV??head.nativeNAV??null,rows=head.core?.rowsCounts?.decisions??head.rowsCounts?.decisions??head.decisionRows??0,ledgerComplete=Number.isSafeInteger(total)&&total>0&&processed===total&&rows===total,complete=nav?.complete===true&&nav.sameAsOf===true&&nav.observations===total&&nav.currency===head.config.quoteCurrency&&Array.isArray(nav.missing)&&nav.missing.length===0;
 return {basis:'PERSISTED_SIMULATION_DECISION_READINESS_V1',executionMode:head.config.mode,status:!processed?'NOT_EXECUTED':!ready?'NO_EVALUABLE_DECISIONS':!completed?'IN_PROGRESS':warmup||!ledgerComplete||!complete?'PARTIAL_WINDOW':'FULL_WINDOW',readyDecisions:ready,warmupDecisions:warmup,processedDecisions:processed,totalDecisions:total,wholeWindowComparable:completed&&ready===total&&ledgerComplete&&complete,metricsBasis:'ACCOUNT_LEDGER',originalMetricsPreserved:true,valuation:{status:!completed?'PENDING':complete&&ledgerComplete?'COMPLETE':'PARTIAL',reason:completed&&!complete?'INCOMPLETE_NATIVE_EVENT_NAV':completed&&!ledgerComplete?'INCOMPLETE_EVENT_DECISION_LEDGER':null,quoteCurrency:head.config.quoteCurrency,requiredAsOf:head.config.endAt,decisionLedgerComplete:ledgerComplete,nativeNAV:nav?structuredClone(nav):null}};
}

function eventEvaluationEligibility(head){
 const processed=head.core?.cursor??head.core?.rowsCounts?.decisions??head.processed??head.progress?.processed??head.progress?.completed??head.rowsCounts?.decisions??head.report?.rowsCounts?.decisions??0;
 const warmup=head.core?.totals?.warmupCount??head.warmup??head.report?.quality?.warmupCount??0,ready=Math.max(0,processed-warmup),total=head.core?.coverage?.totalDecisionFrames??head.coverage?.totalDecisionFrames??head.total??head.progress?.total??head.report?.coverage?.totalDecisionFrames??0;
 const decisionRows=head.core?.rowsCounts?.decisions??head.rowsCounts?.decisions??head.report?.rowsCounts?.decisions,countsConsistent=Number.isSafeInteger(processed)&&processed>=0&&Number.isSafeInteger(total)&&total>0&&Number.isSafeInteger(warmup)&&warmup>=0&&warmup<=processed&&(decisionRows===undefined||decisionRows===processed),completed=head.status==='COMPLETED',completeDecisions=countsConsistent&&processed===total;
 const reference=head.core?.referenceNAV??head.report?.referenceNAV??head.referenceNAV??null,incompleteFrames=head.core?.totals?.incompleteValuationFrames??head.incompleteValuationFrames??head.report?.quality?.incompleteValuationFrames??0;
 const completeReference=reference?.currency==='BTC'&&reference.complete===true&&reference.sameAsOf===true&&reference.observations===total&&Array.isArray(reference.missing)&&reference.missing.length===0&&incompleteFrames===0;
 const wholeWindowComparable=completed&&completeDecisions&&ready===total&&completeReference,partial=warmup>0||!completeDecisions||!completeReference,reason=!reference?'MISSING_BTC_REFERENCE_NAV':!completeReference?'INCOMPLETE_EVENT_REFERENCE_NAV':!completeDecisions?'INCOMPLETE_EVENT_DECISION_LEDGER':null;
 return {basis:'PERSISTED_SIMULATION_DECISION_READINESS_V1',executionMode:head.config?.mode,status:!processed?'NOT_EXECUTED':!ready?'NO_EVALUABLE_DECISIONS':!completed?'IN_PROGRESS':partial?'PARTIAL_WINDOW':'FULL_WINDOW',readyDecisions:ready,warmupDecisions:warmup,processedDecisions:processed,totalDecisions:total,wholeWindowComparable,metricsBasis:'ACCOUNT_LEDGER',originalMetricsPreserved:true,valuation:{status:!completed?'PENDING':completeReference&&completeDecisions?'COMPLETE':'PARTIAL',reason:completed?reason:null,quoteCurrency:'BTC',nativeQuoteCurrency:head.config?.quoteCurrency??head.core?.account?.quoteCurrency??head.account?.quoteCurrency??null,requiredAsOf:head.config?.endAt??null,incompleteFrames,decisionLedgerComplete:completeDecisions,referenceNAV:reference?structuredClone(reference):null}};
}
